llm_calls.content:
{
  "task_summary": "Predict whether an adult is employed, favoring signals that reflect broadly portable labor-force attachment rather than state-specific demographic composition.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is a core, state-stable determinant of labor-force participation over the life cycle."
    },
    {
      "rank": 2,
      "feature_id": 1,
      "rationale": "Educational attainment strongly and consistently predicts employment across states."
    },
    {
      "rank": 3,
      "feature_id": 4,
      "rationale": "Disability status directly affects ability to work and should generalize well geographically."
    },
    {
      "rank": 4,
      "feature_id": 13,
      "rationale": "Cognitive difficulty is a strong functional limitation closely tied to employment capacity."
    },
    {
      "rank": 5,
      "feature_id": 8,
      "rationale": "Military service status captures a broadly meaningful labor-market pathway and retirement pattern."
    },
    {
      "rank": 6,
      "feature_id": 11,
      "rationale": "Hearing difficulty is a portable health-related predictor of employment barriers."
    },
    {
      "rank": 7,
      "feature_id": 12,
      "rationale": "Vision difficulty is another general functional limitation relevant to employability."
    },
    {
      "rank": 8,
      "feature_id": 2,
      "rationale": "Marital status correlates with household roles and labor-force attachment, though less directly."
    },
    {
      "rank": 9,
      "feature_id": 6,
      "rationale": "Citizenship status affects legal access and integration into work, but can partly proxy geography."
    },
    {
      "rank": 10,
      "feature_id": 10,
      "rationale": "Nativity has some broad relevance to employment but overlaps with citizenship and migration patterns."
    },
    {
      "rank": 11,
      "feature_id": 7,
      "rationale": "Recent mobility may relate to job transitions, but its meaning can vary with local housing and migration patterns."
    },
    {
      "rank": 12,
      "feature_id": 14,
      "rationale": "Sex is predictive in practice but risks encoding demographic shortcuts rather than portable causal structure."
    },
    {
      "rank": 13,
      "feature_id": 3,
      "rationale": "Relationship to householder mainly reflects household composition and can act as an indirect shortcut."
    },
    {
      "rank": 14,
      "feature_id": 15,
      "rationale": "Race often predicts through structural disparities that vary across states, making it brittle for OOD use."
    },
    {
      "rank": 15,
      "feature_id": 9,
      "rationale": "Ancestry is largely a demographic/geographic proxy with weak direct semantic connection to employment."
    },
    {
      "rank": 16,
      "feature_id": 5,
      "rationale": "Parental employment is mainly defined for children and is minimally relevant for the adult employment task."
    }
  ]
}
